import{_ as e,a0 as l,w as n,s as p,ao as u,I as s,x as o,a1 as r,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const _=JSON.parse('{"title":"Linux 有問必答：如何從VirtualBox中從主機訪問NAT客户機 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 有問必答：如何從VirtualBox中從主機訪問NAT客户機 | LCTT (201412) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 有問必答：如何從VirtualBox中從主機訪問NAT客户機 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 有問必答：如何從VirtualBox中從主機訪問NAT客户機 | LCTT (201412) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201412/20141125 Linux FAQs with Answers--How to access a NAT guest from host with VirtualBox","title":"Linux 有問必答：如何從VirtualBox中從主機訪問NAT客户機","tag":"201412","desc":""},"relativePath":"201412/20141125 Linux FAQs with Answers--How to access a NAT guest from host with VirtualBox.md","filePath":"[post].md"}'),x={name:"201412/20141125 Linux FAQs with Answers--How to access a NAT guest from host with VirtualBox.md"};function m(g,t,c,f,T,d){const a=l("Link");return n(),p("div",null,[t[11]||(t[11]=u(`<h1 id="linux-有問必答-如何從virtualbox中從主機訪問nat客户機" tabindex="-1">Linux 有問必答：如何從VirtualBox中從主機訪問NAT客户機 <a class="header-anchor" href="#linux-有問必答-如何從virtualbox中從主機訪問nat客户機" aria-label="Permalink to “Linux 有問必答：如何從VirtualBox中從主機訪問NAT客户機”">​</a></h1><blockquote><p><strong>提問</strong>: 我有一台運行在VirtualBox上的使用NAT的虛擬機，因此虛擬機會被VirtualBox分配一個私有IP地址(10.x.x.x)。如果我想要從主機SSH到虛擬機中，我該怎麼做？</p></blockquote><p>VirtualBox對虛擬機支持幾種不同的網絡方式，其中一種是NAT網絡。當虛擬機啓用NAT後，VirtualBox會自動在虛擬機和主機之間進行網絡翻譯，因此你不必在虛擬機和主機之間配置任何東西。這也意味着NAT中的虛擬機對於外部網絡以及主機本身是不可見的。這會在你想要從主機訪問虛擬機時會產生問題（比如SSH）。</p><p>如果你想從VirtualBox的NAT環境的虛擬機，你可以在GUI或者命令列下啓用VirtualBox NAT的端口轉發。本篇教程將會演示<strong>如何通過啓用22端口轉發而從主機SSH連接到NAT環境的客户機</strong>。如果你先想要從HTTP訪問NAT的客户機，用80端口代替22端口即可。</p><h3 id="通過gui配置virtualbox端口轉發" tabindex="-1">通過GUI配置VirtualBox端口轉發 <a class="header-anchor" href="#通過gui配置virtualbox端口轉發" aria-label="Permalink to “通過GUI配置VirtualBox端口轉發”">​</a></h3><p>在VirtualBox中選擇你想要訪問的虛擬機，打開虛擬機的“設置”。點擊左側的“網絡”菜單，點擊網絡適配選項的“高級”。</p><p><img src="https://farm8.staticflickr.com/7583/15797904856_2753dc785e_z.jpg" alt=""></p><p>點擊“端口轉發”按鈕</p><p><img src="https://farm8.staticflickr.com/7527/15636152708_cf2be7c7e8_z.jpg" alt=""></p><p>你會看到一個配置端口轉發規則的窗口。點擊右上角的“添加”圖標。</p><p><img src="https://farm8.staticflickr.com/7489/15636391217_48a9954480_z.jpg" alt=""></p><p>就會看到像下面那樣的轉發規則。</p><ul><li><strong>Name</strong>: SSH (可以是任意唯一名)</li><li><strong>Protocol</strong>: TCP</li><li><strong>Host IP</strong>: 127.0.0.1</li><li><strong>Host Port</strong>: 2222 (任何大於1024未使用的端口)</li><li><strong>Guest IP</strong>: 虛擬機IP</li><li><strong>Guest Port</strong>: 22 (SSH 端口)</li></ul><p><img src="https://farm6.staticflickr.com/5603/15202135853_02a07c3212_o.png" alt=""></p><p>端口轉發的規則會自動在你啓動虛擬機的時候啓用。為了驗證。可以在你啓用虛擬機後檢查端口2222是否被VirtualBox開啓了。</p><pre><code>$ sudo netstat -nap | grep 2222 
</code></pre><p><img src="https://farm8.staticflickr.com/7461/15819682411_6bb9707f8a_z.jpg" alt=""></p><p>現在端口轉發可以使用了，你可以用下面的命令SSH到虛擬機。</p><pre><code> $ ssh -p 2222 &lt;login&gt;@127.0.0.1 
</code></pre><p>發送到127.0.0.1:2222的登錄請求會自動被VirtualBox翻譯成10.0.2.15:22，這可以讓你SSH到虛擬機中。</p><h3 id="通過命令列配置virtualbox端口轉發" tabindex="-1">通過命令列配置VirtualBox端口轉發 <a class="header-anchor" href="#通過命令列配置virtualbox端口轉發" aria-label="Permalink to “通過命令列配置VirtualBox端口轉發”">​</a></h3><p>VirtualBox有一個稱為VBoxManage的命令列管理工具。使用命令列工具，你也可以為你的虛擬機設置端口轉發。</p><p>下面的命令會為IP地址為10.0.2.15的虛擬機設置一個名字為&quot;centos7&quot;的端口轉發規則，SSH的端口號為22,映射到本地主機的端口為2222。規則的名字（本例中是SSH）必須是唯一的。</p><pre><code>$ VBoxManage modifyvm &quot;centos7&quot; --natpf1 &quot;SSH,tcp,127.0.0.1,2222,10.0.2.15,22&quot; 
</code></pre><p>規則創建之後，你可以用下面的命令來驗證。</p><pre><code> $ VBoxManage showvminfo &quot;centos7&quot; | grep NIC 
</code></pre><p><img src="https://farm8.staticflickr.com/7559/15636458427_7a0959900c_z.jpg" alt=""></p><hr>`,28)),s("p",null,[t[1]||(t[1]=o("via: ",-1)),r(a,{href:"http://ask.xmodulo.com/access-nat-guest-from-host-virtualbox.html"},{default:i(()=>[...t[0]||(t[0]=[o("http://ask.xmodulo.com/access-nat-guest-from-host-virtualbox.html",-1)])]),_:1})]),s("p",null,[t[4]||(t[4]=o("譯者：",-1)),r(a,{href:"https://github.com/geekpi"},{default:i(()=>[...t[2]||(t[2]=[o("geekpi",-1)])]),_:1}),t[5]||(t[5]=o(" 校對：",-1)),r(a,{href:"https://github.com/wxy"},{default:i(()=>[...t[3]||(t[3]=[o("wxy",-1)])]),_:1})]),s("p",null,[t[8]||(t[8]=o("本文由 ",-1)),r(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[6]||(t[6]=[o("LCTT",-1)])]),_:1}),t[9]||(t[9]=o(" 原創翻譯，",-1)),r(a,{href:"http://linux.cn/"},{default:i(()=>[...t[7]||(t[7]=[o("Linux中國",-1)])]),_:1}),t[10]||(t[10]=o(" 榮譽推出",-1))])])}const A=e(x,[["render",m]]);export{_ as __pageData,A as default};
